-- DIGITAL CAMERAS & PHOTOGRAPHY (10 products)
('canon-eos-r8-mark-ii', 'Canon EOS R8 Mark II Full-Frame Mirrorless Camera Body - Black', 'cameras', 1450000, 1420000, 1250000, 4, 0.46, '/assets/products/canon-r8-ii.jpg', 'Full-frame performance in an impossibly compact body. The R8 Mark II features a 30.3MP stacked CMOS sensor, DIGIC X+ processor, 40fps electronic shutter, and Canon''s most advanced Dual Pixel CMOS AF VI with subject detection for humans, animals, and vehicles.', 1, unixepoch('2026-06-16'), 1, 1250000, '/assets/products/canon-r8-ii.jpg', 1350000, 4.8, 1, 'Canon', 1, 1),

('sony-a7c-ii-r', 'Sony Alpha a7C II R 61MP Full-Frame Compact Camera - Silver', 'cameras', 2250000, 2190000, 1920000, 3, 0.51, '/assets/products/sony-a7c-ii-r.jpg', 'Medium format resolution in a rangefinder-style body. The a7C II R packs Sony''s stunning 61MP full-frame sensor into the world''s smallest and lightest high-resolution camera, with AI-powered Real-time Recognition AF and 8-stop IBIS for handheld pixel-sharp images.', 1, unixepoch('2026-06-16'), 1, 1920000, '/assets/products/sony-a7c-ii-r.jpg', 2080000, 4.9, 1, 'Sony', 1, 1),

('fujifilm-x-t60', 'Fujifilm X-T60 40.2MP APS-C Mirrorless Camera - Charcoal Silver', 'cameras', 950000, 929000, 810000, 5, 0.49, '/assets/products/fujifilm-x-t60.jpg', 'The classic analog dials and timeless design hide Fujifilm''s most advanced APS-C sensor. With 40.2MP resolution, the renowned Film Simulation modes now including REALA ACE, and 7-stop IBIS, the X-T60 makes every shot worthy of framing.', 1, unixepoch('2026-06-16'), 1, 810000, '/assets/products/fujifilm-x-t60.jpg', 880000, 4.7, 1, 'Fujifilm', 1, 1),

('nikon-z6-iv', 'Nikon Z6 IV 33MP Full-Frame Mirrorless Camera with 8K Video', 'cameras', 1850000, 1790000, 1580000, 4, 0.68, '/assets/products/nikon-z6-iv.jpg', 'The hybrid shooter''s ultimate tool. The Z6 IV captures stunning 33MP stills and 8K/60p internal RAW video with Nikon''s legendary color science. The EXPEED 8 processor enables Real-Live EVF with zero blackout and 120fps continuous shooting.', 1, unixepoch('2026-06-16'), 1, 1580000, '/assets/products/nikon-z6-iv.jpg', 1680000, 4.8, 0, 'Nikon', 1, 1),

('gopro-hero-14-black', 'GoPro HERO14 Black Action Camera with HyperSmooth 7.0', 'cameras', 380000, 369000, 315000, 8, 0.15, '/assets/products/gopro-hero14.jpg', 'The undisputed king of action cameras. The HERO14 Black captures 6K/120fps video with HyperSmooth 7.0 stabilization that rivals a gimbal, a new 1/1.3-inch sensor for incredible low-light performance, and Horizon Lock that keeps your footage level through 360° rotation.', 1, unixepoch('2026-06-16'), 1, 315000, '/assets/products/gopro-hero14.jpg', 348000, 4.8, 1, 'GoPro', 1, 1),

('dji-osmo-pocket-4', 'DJI Osmo Pocket 4 3-Axis Gimbal Camera with 1" Sensor', 'cameras', 420000, 409000, 355000, 6, 0.18, '/assets/products/dji-pocket-4.jpg', 'Cinematic stabilization that fits in your pocket. The Pocket 4 features a 1-inch sensor, 4K/120fps recording, a rotating 2.5-inch touchscreen for portrait and landscape, and ActiveTrack 5.0 that keeps subjects perfectly framed as you move.', 1, unixepoch('2026-06-16'), 1, 355000, '/assets/products/dji-pocket-4.jpg', 388000, 4.7, 1, 'DJI', 1, 1),

('insta360-x5', 'Insta360 X5 8K 360-Degree Action Camera - Black', 'cameras', 380000, 369000, 315000, 6, 0.18, '/assets/products/insta360-x5.jpg', 'Shoot first, frame later. Dual 1-inch sensors capture everything in stunning 8K 360°, letting you reframe the perfect shot after the fact. The invisible selfie stick, FlowState stabilization, and AI-powered editing make creating impossible shots effortless.', 1, unixepoch('2026-06-16'), 1, 315000, '/assets/products/insta360-x5.jpg', 348000, 4.7, 1, 'Insta360', 1, 1),

('canon-selphy-qx30', 'Canon SELPHY QX30 Portable Wireless Photo Printer - Rose Gold', 'cameras', 125000, 119000, 98000, 10, 0.65, '/assets/products/canon-selphy-qx30.jpg', 'Print your memories instantly from anywhere. The QX30 produces lab-quality 4x6 prints in 47 seconds using dye-sublimation technology that resists water and fading for 100 years. Built-in WiFi and the Canon PRINT app make printing from any phone effortless.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/canon-selphy-qx30.jpg', 112000, 4.6, 1, 'Canon', 1, 1),

('peak-design-capture-clip-v4', 'Peak Design Capture Camera Clip V4 - Silver', 'accessories', 65000, 63900, 52000, 15, 0.11, '/assets/products/peak-capture-v4.jpg', 'Carry your camera on any backpack strap or belt with instant access. The Capture V4 features a quick-release button that''s operable with gloves, an anodized aluminum body rated for 90kg load, and compatibility with all Peak Design plates and tripods.', 1, unixepoch('2026-06-16'), 1, 52000, '/assets/products/peak-capture-v4.jpg', 59000, 4.8, 1, 'Peak Design', 1, 1),

('sandisk-extreme-pro-cfexpress-512gb', 'SanDisk Extreme PRO CFexpress Card Type B 512GB 1700MB/s', 'cameras', 125000, 119000, 98000, 12, 0.01, '/assets/products/sandisk-cfexpress-512.jpg', 'Sustained write speeds of 1500MB/s handle 8K RAW video without dropping a single frame. With 512GB capacity and SanDisk''s legendary reliability, this CFexpress card is the trusted choice of professional photographers and cinematographers worldwide.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/sandisk-cfexpress-512.jpg', 112000, 4.8, 1, 'SanDisk', 1, 1),

-- CAR ELECTRONICS & DASH CAMS (8 products)
('garmin-dash-cam-mini-4', 'Garmin Dash Cam Mini 4 1440p HDR with Parking Guard - Black', 'car-electronics', 85000, 82900, 68000, 18, 0.06, '/assets/products/garmin-mini-4.jpg', 'Tiny but mighty protection for your vehicle. The Mini 4 is smaller than a car key yet records 1440p HDR video with a 140° wide-angle lens. Voice control, automatic incident detection, and Parking Guard mode protect your car 24/7.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/garmin-mini-4.jpg', 78000, 4.6, 1, 'Garmin', 1, 1),

('viofo-a329-pro', 'VIOFO A329 Pro 3-Channel 4K Dash Cam with Sony STARVIS 3', 'car-electronics', 185000, 179000, 148000, 10, 0.32, '/assets/products/viofo-a329.jpg', 'Complete coverage of front, rear, and interior with three Sony STARVIS 3 sensors. The A329 Pro captures 4K front, 2K rear, and 1080p cabin footage simultaneously, with built-in 5GHz WiFi for instant video transfer and GPS for speed and location logging.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/viofo-a329.jpg', 168000, 4.5, 1, 'VIOFO', 1, 1),

('thinkware-u5000', 'Thinkware U5000 4K Cloud Dash Cam with AI Driver Assistance', 'car-electronics', 220000, 215000, 178000, 8, 0.28, '/assets/products/thinkware-u5000.jpg', 'Connected car protection with real-time cloud upload. The U5000 warns of potential collisions, lane departures, and speed cameras, while automatically uploading incident footage to the cloud via built-in LTE. Advanced parking mode monitors your vehicle for impacts.', 1, unixepoch('2026-06-16'), 1, 178000, '/assets/products/thinkware-u5000.jpg', 205000, 4.6, 0, 'Thinkware', 1, 1),

('carlinkit-6-0-wireless-carplay', 'Carlinkit 6.0 Wireless CarPlay & Android Auto Adapter 2-in-1', 'car-electronics', 28000, 26900, 22500, 35, 0.04, '/assets/products/carlinkit-6.jpg', 'Transform your wired CarPlay into seamless wireless freedom in seconds. This tiny adapter plugs into your car''s USB port and automatically connects your phone when you start the engine, with zero lag and support for steering wheel controls.', 1, unixepoch('2026-06-16'), 1, 22500, '/assets/products/carlinkit-6.jpg', 25500, 4.4, 1, 'Carlinkit', 1, 1),

('nextbase-iq-smart-dashcam', 'Nextbase iQ AI-Powered 4K Smart Dash Cam with 4G LTE', 'car-electronics', 250000, 245000, 215000, 6, 0.35, '/assets/products/nextbase-iq.jpg', 'The most intelligent dash cam ever made. The iQ uses AI to recognize aggressive driving, distracted driving, and potential hazards, alerting you in real-time. 4G connectivity enables remote live view, theft alerts, and emergency SOS calling with your location.', 1, unixepoch('2026-06-16'), 1, 215000, '/assets/products/nextbase-iq.jpg', 235000, 4.5, 0, 'Nextbase', 1, 1),

('roav-smartcharge-spectra', 'ROAV SmartCharge Spectra Pro 90W Car Charger with FM Transmitter', 'car-electronics', 18500, 17900, 14500, 40, 0.09, '/assets/products/roav-spectra-pro.jpg', 'Revive your older car with modern tech. The Spectra Pro adds Bluetooth 5.4 streaming and hands-free calling via FM transmission, while its 90W GaN charger fast-charges a laptop and phone simultaneously. The companion app finds the clearest FM frequency automatically.', 1, unixepoch('2026-06-16'), 1, 14500, '/assets/products/roav-spectra-pro.jpg', 16800, 4.4, 1, 'ROAV', 1, 1),

('garmin-drivesmart-76', 'Garmin DriveSmart 76 7" GPS Navigator with Lifetime Maps Africa', 'car-electronics', 185000, 179000, 148000, 10, 0.28, '/assets/products/garmin-drivesmart-76.jpg', 'Navigate Nigeria and West Africa with confidence using lifetime map updates and Garmin''s most accurate GPS. The 7-inch edge-to-edge display, voice-activated navigation, and real-time traffic alerts via the Garmin Drive app keep you on the best route.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/garmin-drivesmart-76.jpg', 168000, 4.5, 0, 'Garmin', 1, 1),

('type-s-jump-starter-8000a', 'TYPE S 8000A Lithium Jump Starter with 100W PD & LED Floodlight', 'car-electronics', 125000, 119000, 98000, 12, 1.35, '/assets/products/types-jumpstarter.jpg', 'The most powerful portable jump starter you can buy. With 8000A peak current, it starts completely dead 12L diesel engines effortlessly. The 100W USB-C PD port charges your laptop, while the 600-lumen LED floodlight with SOS mode is essential for Nigerian roadside emergencies.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/types-jumpstarter.jpg', 112000, 4.6, 1, 'TYPE S', 1, 1),

-- PORTABLE STORAGE & MEMORY SOLUTIONS (8 products)
('samsung-t9-shield-4tb', 'Samsung T9 Shield 4TB Portable USB-C SSD - IP65 Rugged', 'storage', 320000, 315000, 268000, 6, 0.12, '/assets/products/samsung-t9-shield.jpg', 'Your data is invincible in the face of dust, rain, and 3-meter drops. The T9 Shield delivers 2,000MB/s transfer speeds in a rugged IP65-rated body, making it the go-to portable drive for photographers, videographers, and content creators working in tough Nigerian conditions.', 1, unixepoch('2026-06-16'), 1, 268000, '/assets/products/samsung-t9-shield.jpg', 298000, 4.8, 1, 'Samsung', 1, 1),

('sandisk-extreme-pro-v4-2tb', 'SanDisk Extreme PRO v4 2TB Portable SSD 4000MB/s', 'storage', 250000, 245000, 215000, 8, 0.08, '/assets/products/sandisk-extreme-pro-v4.jpg', 'Thunderbolt-fast speeds in a pocket-sized drive. With 4,000MB/s read and 3,800MB/s write speeds, this SanDisk drive transfers a 50GB 4K video file in under 15 seconds. Forged aluminum chassis dissipates heat for sustained performance during marathon editing sessions.', 1, unixepoch('2026-06-16'), 1, 215000, '/assets/products/sandisk-extreme-pro-v4.jpg', 235000, 4.8, 1, 'SanDisk', 1, 1),

('wd-black-p50-game-drive-5tb', 'WD_BLACK P50 Game Drive 5TB NVMe SSD with RGB - Black', 'storage', 350000, 339000, 288000, 5, 0.14, '/assets/products/wd-black-p50-5tb.jpg', 'Never delete a game again. With 5TB of NVMe storage and 2,000MB/s speeds, the P50 stores your entire game library—from Call of Duty to GTA—with room to spare. Customizable RGB lighting syncs with your gaming setup via WD_BLACK Dashboard.', 1, unixepoch('2026-06-16'), 1, 288000, '/assets/products/wd-black-p50-5tb.jpg', 318000, 4.7, 0, 'WD_BLACK', 1, 1),

('lexar-professional-cfexpress-1tb', 'Lexar Professional CFexpress Type A Gold 1TB 900MB/s', 'storage', 185000, 179000, 148000, 8, 0.01, '/assets/products/lexar-cfexpress-1tb.jpg', 'Designed for Sony Alpha and FX series cameras. This CFexpress Type A card delivers sustained write speeds of 800MB/s for uninterrupted 8K video capture, with 1TB capacity that stores hours of footage. Lexar''s lifetime limited warranty ensures peace of mind.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/lexar-cfexpress-1tb.jpg', 168000, 4.7, 1, 'Lexar', 1, 1),

('kingston-canvas-react-plus-512gb', 'Kingston Canvas React Plus 512GB UHS-II SDXC Card 300MB/s', 'storage', 45000, 43900, 36500, 15, 0.01, '/assets/products/kingston-react-plus.jpg', 'Pro-level burst shooting without buffer delays. With 300MB/s read and 260MB/s write speeds, this UHS-II U3 V90 SD card handles continuous RAW burst from high-resolution cameras effortlessly, making it the trusted choice for wedding and sports photographers.', 1, unixepoch('2026-06-16'), 1, 36500, '/assets/products/kingston-react-plus.jpg', 41500, 4.7, 1, 'Kingston', 1, 1),

('sabrent-rocket-nano-v2-4tb', 'Sabrent Rocket Nano V2 4TB Portable SSD 2760MB/s - Titanium Grey', 'storage', 280000, 275000, 235000, 5, 0.09, '/assets/products/sabrent-rocket-nano-4tb.jpg', 'Massive capacity in a device smaller than a credit card. The Rocket Nano V2 stores 4TB at 2,760MB/s—enough for 800,000 photos or 1,000 hours of HD video. The durable aluminum enclosure with an included silicone sleeve survives life on the road.', 1, unixepoch('2026-06-16'), 1, 235000, '/assets/products/sabrent-rocket-nano-4tb.jpg', 258000, 4.6, 0, 'Sabrent', 1, 1),

('crucial-x10-pro-4tb', 'Crucial X10 Pro 4TB Portable SSD 2100MB/s with Hardware Encryption', 'storage', 250000, 245000, 215000, 6, 0.07, '/assets/products/crucial-x10-pro.jpg', 'Military-grade security for your most sensitive files. The X10 Pro features AES 256-bit hardware encryption with a password-protected interface, ensuring your data remains inaccessible even if the drive is lost. IP55 dust and water resistance for field reliability.', 1, unixepoch('2026-06-16'), 1, 215000, '/assets/products/crucial-x10-pro.jpg', 235000, 4.6, 0, 'Crucial', 1, 1),

('sandisk-ultra-dual-drive-luxe-1tb', 'SanDisk Ultra Dual Drive Luxe USB-C & USB-A 1TB Flash Drive', 'storage', 65000, 63900, 52000, 20, 0.03, '/assets/products/sandisk-dual-luxe-1tb.jpg', 'Effortlessly move files between your phone, tablet, and computer with dual USB-C and USB-A connectors. The 1TB capacity fits an entire media library on a device the size of a paperclip, with a swivel design that protects connectors and attaches to your keychain.', 1, unixepoch('2026-06-16'), 1, 52000, '/assets/products/sandisk-dual-luxe-1tb.jpg', 59000, 4.7, 1, 'SanDisk', 1, 1),

-- HIGH-PERFORMANCE CABLES & ADAPTERS (8 products)
('cable-matters-thunderbolt-5-1m', 'Cable Matters Intel-Certified Thunderbolt 5 Cable 1m 120Gbps', 'accessories', 38000, 36900, 30500, 20, 0.08, '/assets/products/cablematters-tb5.jpg', 'Unlock the full potential of Thunderbolt 5 with Intel-certified 120Gbps bi-directional bandwidth. This cable drives three 8K displays, connects external GPUs, and delivers 240W of power simultaneously through a single, durable braided cable.', 1, unixepoch('2026-06-16'), 1, 30500, '/assets/products/cablematters-tb5.jpg', 34800, 4.7, 1, 'Cable Matters', 1, 1),

('belkin-connect-pro-thunderbolt-5-dock', 'Belkin Connect Pro Thunderbolt 5 Dock 14-in-1 with GaN 240W', 'accessories', 380000, 369000, 315000, 5, 1.1, '/assets/products/belkin-tb5-dock.jpg', 'Transform a single Thunderbolt 5 port into a complete desktop workstation. Four Thunderbolt 5 downstream ports, dual 8K HDMI, 10GbE Ethernet, UHS-II SD reader, and 240W host charging make this the definitive docking solution for creative professionals.', 1, unixepoch('2026-06-16'), 1, 315000, '/assets/products/belkin-tb5-dock.jpg', 348000, 4.7, 1, 'Belkin', 1, 1),

('club3d-cac-1083-displayport', 'Club3D CAC-1083 DisplayPort 2.1 to HDMI 2.1 Active Adapter 8K60', 'accessories', 25000, 23900, 19500, 25, 0.05, '/assets/products/club3d-dp-hdmi.jpg', 'Certified to convert DisplayPort 2.1 signals to full HDMI 2.1 bandwidth for 8K/60Hz or 4K/240Hz on your TV. This active adapter supports VRR, ALLM, and HDR metadata passthrough, making it essential for connecting gaming PCs to large-screen televisions.', 1, unixepoch('2026-06-16'), 1, 19500, '/assets/products/club3d-dp-hdmi.jpg', 22500, 4.6, 1, 'Club3D', 1, 1),

('uni-usb-c-to-displayport-8k', 'uni USB-C to DisplayPort 2.1 Cable 8K/60Hz 2m Braided', 'accessories', 22000, 21500, 17500, 30, 0.12, '/assets/products/uni-usbc-dp21.jpg', 'A single cable connecting your USB-C laptop to any DisplayPort monitor at up to 8K resolution. The braided nylon jacket, reinforced stress points, and gold-plated connectors are rated for 15,000 plug cycles—built to outlast your laptop.', 1, unixepoch('2026-06-16'), 1, 17500, '/assets/products/uni-usbc-dp21.jpg', 20500, 4.6, 1, 'uni', 1, 1),

('startech-usb-c-multiport-adapter', 'StarTech.com USB-C Multiport Adapter with 2.5GbE & 100W PD', 'accessories', 45000, 43900, 36500, 18, 0.10, '/assets/products/startech-multiport.jpg', 'StarTech''s enterprise-grade adapter provides reliable connectivity for business laptops. The 2.5GbE port, dual 4K HDMI, and 100W passthrough charging are backed by a 3-year warranty and lifetime technical support that IT departments trust.', 1, unixepoch('2026-06-16'), 1, 36500, '/assets/products/startech-multiport.jpg', 41500, 4.5, 0, 'StarTech', 1, 1),

('deity-microphone-cables-xlr', 'Deity Microphones XLR Cable 3m with Neutrik Connectors - 2-Pack', 'audio', 35000, 33900, 28500, 15, 0.55, '/assets/products/deity-xlr-3m.jpg', 'Swiss-made Neutrik connectors and oxygen-free copper conductors deliver pristine audio with zero interference. This 2-pack of 3-meter XLR cables is individually tested for signal integrity, ensuring your recordings are free from hum, buzz, and dropouts.', 1, unixepoch('2026-06-16'), 1, 28500, '/assets/products/deity-xlr-3m.jpg', 31800, 4.7, 1, 'Deity', 1, 1),

('magnetic-usb-c-adapter-24pin', '24-Pin Magnetic USB-C Adapter 240W PD with 40Gbps Data', 'accessories', 8500, 8200, 6500, 50, 0.02, '/assets/products/magnetic-usbc-24pin.jpg', 'Protect your devices from port damage and tripping hazards. This 24-pin magnetic adapter snaps apart under tension, supports 240W charging and 40Gbps data, and stays in your device''s USB-C port while the cable magnetically attaches and releases.', 1, unixepoch('2026-06-16'), 1, 6500, '/assets/products/magnetic-usbc-24pin.jpg', 7600, 4.5, 1, 'Generic', 1, 1),

('cable-organizer-desk-tray', 'Under-Desk Cable Management Tray with Power Strip Holder - Steel', 'accessories', 22000, 21500, 17500, 25, 1.45, '/assets/products/cable-tray-steel.jpg', 'Transform the jungle of cables under your desk into a clean, organized workspace. This heavy-duty powder-coated steel tray mounts in minutes with included clamps or screws, holding power strips, excess cables, and power bricks out of sight.', 1, unixepoch('2026-06-16'), 1, 17500, '/assets/products/cable-tray-steel.jpg', 20500, 4.7, 1, 'Generic', 1, 1),

-- PREMIUM AUDIO ACCESSORIES (8 products)
('audeze-maxwell-wireless', 'Audeze Maxwell Ultraviolet Edition Wireless Gaming Headset', 'audio', 320000, 315000, 268000, 5, 0.49, '/assets/products/audeze-maxwell.jpg', 'Audiophile planar magnetic drivers in a gaming headset. The Maxwell delivers an immense 80-hour battery life, the most natural, detailed sound in gaming, and a broadcast-quality boom microphone with AI noise filtering. Hear footsteps before they hear you.', 1, unixepoch('2026-06-16'), 1, 268000, '/assets/products/audeze-maxwell.jpg', 298000, 4.8, 1, 'Audeze', 1, 1),

('sennheiser-hd-620s-closed', 'Sennheiser HD 620S Closed-Back Audiophile Headphones - Black', 'audio', 280000, 275000, 235000, 8, 0.30, '/assets/products/sennheiser-hd620s.jpg', 'Reference sound in a closed-back design that isolates you from the world. The HD 620S adapts Sennheiser''s legendary open-back tuning for private listening, with a 42mm transducer and 150-ohm impedance that scales beautifully with dedicated headphone amplifiers.', 1, unixepoch('2026-06-16'), 1, 235000, '/assets/products/sennheiser-hd620s.jpg', 258000, 4.7, 0, 'Sennheiser', 1, 1),

('thx-onyx-dac-dongle', 'THX Onyx Premium USB-C DAC/Amp with MQA Rendering - Black', 'audio', 85000, 82900, 68000, 12, 0.02, '/assets/products/thx-onyx.jpg', 'Transform your phone into a hi-fi audio source. The THX AAA amplifier delivers clean, powerful output that drives even demanding headphones, while the ESS ES9281PRO DAC unfolds MQA streams and hi-res audio up to 32-bit/384kHz with astonishing clarity.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/thx-onyx.jpg', 78000, 4.6, 1, 'THX', 1, 1),

('ifi-audio-hip-dac-4', 'iFi Audio hip-dac 4 Portable Balanced DAC/Amp - Sunset Orange', 'audio', 125000, 119000, 98000, 8, 0.15, '/assets/products/ifi-hipdac-4.jpg', 'A pocket-sized powerhouse that elevates every pair of headphones. The hip-dac 4 features a balanced 4.4mm output delivering 400mW of power, XBass+ analog bass boost, and iFi''s PureWave circuit design that achieves vanishingly low distortion and noise.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/ifi-hipdac-4.jpg', 112000, 4.7, 1, 'iFi Audio', 1, 1),

('schiit-magni-unity-2', 'Schiit Magni Unity 2 Headphone Amplifier with Internal DAC - Silver', 'audio', 125000, 119000, 98000, 6, 0.52, '/assets/products/schiit-magni-unity.jpg', 'Made in USA, this compact amplifier delivers 2.8W of clean power into 32 ohms with a built-in ES9018 DAC. The Unity gain stage ensures zero noise floor with IEMs, while the fully discrete current-feedback topology drives even the most demanding planar headphones.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/schiit-magni-unity.jpg', 112000, 4.8, 0, 'Schiit', 1, 1),

('beyerdynamic-dt-700-pro-x', 'Beyerdynamic DT 700 PRO X Closed-Back Studio Headphones', 'audio', 220000, 215000, 178000, 6, 0.35, '/assets/products/beyerdynamic-dt700x.jpg', 'The closed-back studio standard for tracking and mixing. The STELLAR.45 driver and 48-ohm impedance deliver detailed, accurate sound even on mobile devices, while the plush velour ear pads and robust metal headband provide all-day comfort in the studio.', 1, unixepoch('2026-06-16'), 1, 178000, '/assets/products/beyerdynamic-dt700x.jpg', 205000, 4.7, 1, 'Beyerdynamic', 1, 1),

('fosi-audio-za3-amplifier', 'Fosi Audio ZA3 Balanced Stereo Amplifier with VU Meter - Silver', 'audio', 85000, 82900, 68000, 8, 1.15, '/assets/products/fosi-za3.jpg', 'A retro-styled amplifier with modern balanced inputs and a hypnotic analog VU meter. The ZA3 delivers 155W per channel into 4 ohms from a compact chassis, with replaceable op-amps that let you customize the sound signature to your preference.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/fosi-za3.jpg', 78000, 4.5, 0, 'Fosi Audio', 1, 1),

('kanto-yu4-powered-speakers', 'Kanto YU4 Powered Bookshelf Speakers with Bluetooth - Matte White', 'audio', 320000, 315000, 268000, 5, 4.8, '/assets/products/kanto-yu4-white.jpg', 'Canadian-designed powered speakers that fill any room with rich, detailed sound. The 4-inch Kevlar drivers and 1-inch silk dome tweeters are driven by a built-in Class D amplifier, with Bluetooth aptX-HD, phono preamp, and subwoofer output for a complete audio system.', 1, unixepoch('2026-06-16'), 1, 268000, '/assets/products/kanto-yu4-white.jpg', 298000, 4.7, 0, 'Kanto', 1, 1),

-- GAMING SIM RACING & FLIGHT (8 products)
('logitech-g-pro-racing-wheel', 'Logitech G PRO Racing Wheel with Direct Drive & TrueForce - Black', 'gaming', 850000, 829000, 720000, 3, 7.5, '/assets/products/logitech-pro-wheel.jpg', 'Professional-grade direct drive with 11Nm of torque and TRUEFORCE haptics that communicate every bump, tire slip, and engine vibration through your hands. The quick-release system and load cell pedals make this the definitive racing simulator wheel.', 1, unixepoch('2026-06-16'), 1, 720000, '/assets/products/logitech-pro-wheel.jpg', 780000, 4.8, 1, 'Logitech', 1, 1),

('thrustmaster-t818-ferrari', 'Thrustmaster T818 Ferrari SF1000 Edition Direct Drive Wheel Base', 'gaming', 750000, 729000, 635000, 3, 8.2, '/assets/products/thrustmaster-t818.jpg', 'Officially licensed by Ferrari with an authentic F1 steering wheel replica featuring a 4.3-inch display. The 10Nm constant torque direct drive motor and telemetry integration bring the Formula 1 experience into your living room with uncompromising realism.', 1, unixepoch('2026-06-16'), 1, 635000, '/assets/products/thrustmaster-t818.jpg', 695000, 4.7, 0, 'Thrustmaster', 1, 1),

