('turtle-beach-velocityone-flight-2', 'Turtle Beach VelocityOne Flight 2 Universal Control System', 'gaming', 380000, 369000, 315000, 4, 4.2, '/assets/products/turtlebeach-flight-2.jpg', 'A complete flight cockpit for Xbox and PC. The yoke handle with 180° rotation, integrated throttle quadrant, trim wheel, and status display panel simulate real aircraft controls, while the modular design allows expansion with additional rudder pedals and panels.', 1, unixepoch('2026-06-16'), 1, 315000, '/assets/products/turtlebeach-flight-2.jpg', 348000, 4.6, 0, 'Turtle Beach', 1, 1),

('playseat-challenge-x-logitech', 'Playseat Challenge X - Logitech G Edition Folding Racing Cockpit', 'gaming', 250000, 245000, 215000, 5, 12.0, '/assets/products/playseat-challenge-x.jpg', 'A racing cockpit that folds with wheel and pedals still attached, sliding under a bed or into a closet in seconds. The ActiFit breathable seat conforms to your body during long races, while the reinforced pedal plate handles load cell brakes without flex.', 1, unixepoch('2026-06-16'), 1, 215000, '/assets/products/playseat-challenge-x.jpg', 235000, 4.6, 1, 'Playseat', 1, 1),

('meta-quest-4-elite-strap-battery', 'Meta Quest 4 Elite Strap with Battery Pack & Carrying Case', 'gaming', 125000, 119000, 98000, 10, 0.38, '/assets/products/quest4-elite-strap.jpg', 'Double your Quest 4 playtime and improve comfort. The Elite Strap balances the headset''s weight with a rear-mounted 10,000mAh battery pack, while the precision-fit dial and plush memory foam make marathon VR sessions comfortable. Includes an official carrying case.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/quest4-elite-strap.jpg', 112000, 4.6, 1, 'Meta', 1, 1),

('backbone-one-gen3-usb-c', 'Backbone One Gen 3 USB-C Mobile Gaming Controller - PlayStation Edition', 'gaming', 85000, 82900, 68000, 15, 0.19, '/assets/products/backbone-one-gen3.jpg', 'Turn your phone into a PlayStation Portal alternative. The Gen 3 Backbone One features Hall Effect thumbsticks that never drift, analog triggers, and a 3.5mm headphone jack, with the Backbone app unifying your game library across streaming services and native titles.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/backbone-one-gen3.jpg', 78000, 4.5, 1, 'Backbone', 1, 1),

